public class StringPoolDemo {
    public static void main(String[] args) {

        // Literals — both go through the pool
        String s1 = "hello";
        String s2 = "hello";
        System.out.println(s1 == s2);     // true — same pooled object
        System.out.println(s1.equals(s2)); // true — same content

        // new String() is not itself automatically interned — always creates a new heap object
        String s3 = new String("hello");
        System.out.println(s1 == s3);     // false — different objects
        System.out.println(s1.equals(s3)); // true — same content

        // Always use .equals() to compare content — never == for Strings
        // == checks address (are they the same object?)
        // .equals() checks content (do they have the same characters?)
    }
}
```

