public class LiteralVsNew {
    public static void main(String[] args) {

        String s1 = "hello";           // goes to pool
        String s2 = "hello";           // reuses pooled "hello"
        String s3 = new String("hello"); // creates new heap object, skips pool

        // Identity comparison (are they the same object?)
        System.out.println(s1 == s2); // true  — both point to pooled object
        System.out.println(s1 == s3); // false — s3 is a different object

        // Content comparison (do they have the same characters?)
        System.out.println(s1.equals(s2)); // true
        System.out.println(s1.equals(s3)); // true — same text, different object

        // Lesson: always use .equals() for content comparison
        // == is for checking if two variables point to the exact same object
    }
}
