public class PlusOperatorDemo {
    public static void main(String[] args) {
        String name = "World";

        // Single-line — compiler rewrites to StringBuilder chain, efficient
        String greeting = "Hello, " + name + "!";
        // Roughly becomes: new StringBuilder().append("Hello, ").append(name).append("!").toString()
        System.out.println(greeting); // Hello, World!

        // Loop — compiler CANNOT merge iterations, creates new object per iteration
        String[] words = {"Java", " is", " powerful"};
        String slow = "";
        for (String w : words) {
            slow = slow + w;  // new StringBuilder + new String each time
        }

        // Correct approach — create StringBuilder once before the loop
        StringBuilder sb = new StringBuilder();
        for (String w : words) {
            sb.append(w);  // write to same buffer every time
        }
        String fast = sb.toString();  // one String at the very end
        System.out.println(fast); // Java is powerful
    }
}
